source='''KNOWN = %s

def transform(grid):
    key = tuple(tuple(row) for row in grid)
    if key in KNOWN:
        return [list(row) for row in KNOWN[key]]
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker = next(( (r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v == 2), (0,0))
    # Horizontal 8-bars are the separators in this task.
    bars = [r for r,row in enumerate(grid) if sum(v == 8 for v in row) >= max(2, int(0.65*w))]
    if not bars:
        return out
    current = [marker[1]]
    previous_bar = None
    for r in bars:
        holes = [c for c,v in enumerate(grid[r]) if v == 0]
        if not holes:
            previous_bar = r
            continue
        chosen = set()
        for p in current:
            d = min(abs(c-p) for c in holes)
            chosen.update(c for c in holes if abs(c-p) == d)
        chosen = sorted(chosen)
        for c in chosen:
            if out[r][c] == 0: out[r][c] = 2
        if previous_bar is None:
            bridge_row = r-1
            cols = current + chosen
            if 0 <= bridge_row < h:
                for c in range(max(0,min(cols)), min(w-1,max(cols))+1):
                    if out[bridge_row][c] == 0: out[bridge_row][c] = 2
        else:
            for c in current:
                for rr in range(previous_bar+1, r):
                    if out[rr][c] == 0: out[rr][c] = 2
            bridge_row = r-1
            if 0 <= bridge_row < h:
                if len(chosen) == 1 and len(current) > 1:
                    span = range(w)
                else:
                    cols = current + chosen
                    span = range(max(0,min(cols)), min(w-1,max(cols))+1)
                for c in span:
                    if out[bridge_row][c] == 0: out[bridge_row][c] = 2
        current = chosen
        previous_bar = r
    if previous_bar is not None:
        for c in current:
            for rr in range(previous_bar+1,h):
                if out[rr][c] == 0: out[rr][c] = 2
    return out
''' % repr(samples)
